const D = { energy:.6, scale:1, hue:135, speed:1, density:.5, x:.34, y:.84, chub:.5, neck:.5, tail:.6, spike:.6, pose:'stomp', act:'perform', style:'riso', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------- helpers ----------
const u = Math.min(width, height);
const sc = (u/600) * P.scale;
const ax = P.x*width, ay = P.y*height;
const H = ((P.hue % 360) + 360) % 360;
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.lastBeat = K.beat;

// ---------- rhythm ----------
const e = P.energy, sp = P.speed;
const bt = K.beat * sp, ph = K.phase;
const pulse = Math.min(1, K.pulse*(0.55 + 0.5*K.intensity) + A.bass*0.6);
const liftArc = Math.sin(ph * PI);
const breathe = Math.sin(K.t*0.95)*0.5 + 0.5;
const sway = Math.sin(bt*TAU/8);
const glow = A.bass*0.5 + A.rms*0.6;

// ---------- act ----------
let pose = P.pose;
if (P.act === 'wander') pose = ['idle','stalk','stomp','roar'][K.section % 4];

// ---------- style ----------
const style = P.style;

// ---------- rig math (facing RIGHT) ----------
const chub = P.chub, tl = P.tail, spk = P.spike;
let bodyY=0, bodyX=0, tilt=0, headDX=0, headDY=0, jaw=0, armP=0, legA=0, legB=0, tailA=0;

if (pose === 'stomp') {
  bodyY = -liftArc*(5 + 12*e) - pulse*2;
  bodyX = sway*3;
  headDY = -pulse*4 - liftArc*2;
  legA = Math.max(0, Math.sin(bt*TAU))*(9 + 8*e);
  legB = Math.max(0, -Math.sin(bt*TAU))*(9 + 8*e);
  tailA = Math.sin(bt*TAU/2)*0.5*(0.5 + e*0.6);
  armP = pulse; tilt = sway*0.04;
} else if (pose === 'idle') {
  bodyY = -breathe*3 - K.swell*1.5;
  headDY = Math.sin(bt*TAU/4)*2.2 + pulse*1.5;
  headDX = Math.sin(K.t*0.3)*4;
  tailA = Math.sin(K.t*1.1)*0.4;
  tilt = Math.sin(K.t*0.22)*0.02;
} else if (pose === 'roar') {
  const rear = 0.6 + pulse*0.4;
  tilt = -(0.10 + 0.05*e)*rear;
  bodyY = -pulse*7 - 5;
  headDY = -30 - pulse*16;
  headDX = 8;
  jaw = 0.45 + pulse*0.55 + A.mid*0.2;
  tailA = 0.5 + pulse*0.3;
  armP = 0.6 + pulse*0.4;
} else { // stalk
  bodyY = -Math.abs(Math.sin(bt*TAU))*3 - 3;
  bodyX = sway*4;
  headDX = 12 + Math.sin(K.t*0.4)*5;
  headDY = 12 + Math.sin(bt*TAU/4)*2;
  legA = Math.max(0, Math.sin(bt*TAU))*9;
  legB = Math.max(0, Math.sin(bt*TAU + PI))*9;
  tailA = 0.1 + Math.sin(bt*TAU/4)*0.25;
  tilt = 0.05 + sway*0.03;
}
jaw = Math.min(1, jaw);

const bx = bodyX, byo = bodyY;
const nl = 18 + P.neck*44;
const bellyC = [10 + bx, -96 + byo];
const hipC = [-8 + bx, -80 + byo];
const shC = [34 + bx, -118 + byo];
const neckB = [46 + bx, -130 + byo];
const HDx = neckB[0] + 22 + P.neck*10 + headDX;
const HDy = neckB[1] - nl*0.55 + headDY;
const hr = 40 * (0.85 + chub*0.22);

// ---------- style palette ----------
let riA, riB, boneL, boneD, lpBase;
if (style === 'riso')       { riA=[H,80,84]; riB=[(H+152)%360,72,80]; }
else if (style === 'fossil'){ boneL=[38,16,92]; boneD=[32,34,32]; }
else if (style === 'thermal'){ /* handled inline */ }
else /* lowpoly */          { lpBase=[H,52,58]; }

// build the mass list (drawn back-to-front)
const masses = [];
// tail as tapered polygon
(function(){
  const rootX = hipC[0]-30, rootY = hipC[1]+4;
  const seg = 5, pts=[];
  const bot=[], top=[];
  for (let i=0;i<=seg;i++){
    const t=i/seg;
    const ang = tailA*(0.4 + t*0.9) + Math.sin(K.t*0.7 + t*2)*0.06;
    const dist = (28 + tl*24)*(seg - i*0.0);
    // walk backward/down-left
    const px = rootX - t*(150 + tl*90);
    const py = rootY + t*t*(20) - Math.sin(ang)*t*(40 + tl*40) + 6;
    const w = (30 + chub*14)*(1 - t*0.82);
    top.push([px, py - w*0.5]); bot.push([px, py + w*0.5]);
  }
  for (let i=0;i<top.length;i++) pts.push(top[i]);
  for (let i=bot.length-1;i>=0;i--) pts.push(bot[i]);
  masses.push({k:'poly', pts, d:0.2});
})();
// hind leg (far)
masses.push({k:'ell', x:hipC[0]+2, y:-40+byo-legB, w:30+chub*8, h:60, r:0.05, d:0.25});
masses.push({k:'ell', x:hipC[0]-2, y:2-legB, w:38, h:20, r:0, d:0.2}); // far foot
// belly / body
masses.push({k:'ell', x:bellyC[0], y:bellyC[1], w:150+chub*54, h:150+chub*30, r:0.05, d:0.45});
// hip mass
masses.push({k:'ell', x:hipC[0]+6, y:hipC[1]-6, w:96+chub*20, h:104+chub*18, r:0.1, d:0.35});
// chest/shoulder
masses.push({k:'ell', x:shC[0], y:shC[1]+8, w:74+chub*16, h:88, r:-0.15, d:0.5});
// near leg
masses.push({k:'ell', x:hipC[0]+30, y:-38+byo-legA, w:34+chub*8, h:64, r:-0.05, d:0.4});
masses.push({k:'ell', x:hipC[0]+30, y:4-legA, w:44, h:22, r:0, d:0.35}); // near foot
// neck
masses.push({k:'ell', x:(neckB[0]+HDx)/2, y:(neckB[1]+HDy)/2, w:34+P.neck*6, h:nl+20, r:Math.atan2(HDy-neckB[1], HDx-neckB[0])+PI/2, d:0.5});
// arm (small)
masses.push({k:'ell', x:shC[0]+12, y:shC[1]+26 - armP*4, w:16, h:36 - armP*6, r:0.5 - armP*0.5, d:0.55});

// =============== render ===============
push();
translate(ax, ay);
scale(sc);
translate(bellyC[0]*0 , 0);
rotate(tilt);

// thermal / neon dark aura
if (style === 'thermal') { push(); blendMode(ADD); noStroke(); fill(18, 90, 60, 8 + glow*20 + pulse*4); ellipse(bx, -90, 380, 340); blendMode(BLEND); pop(); }

// contact shadow
noStroke(); fill(0, 0, 0, 22); ellipse(bx, 8, 190 + chub*40, 20);

function geom(m){
  if (m.k === 'ell') { push(); translate(m.x, m.y); rotate(m.r); ellipse(0, 0, m.w, m.h); pop(); }
  else { beginShape(); for (const p of m.pts) vertex(p[0], p[1]); endShape(CLOSE); }
}

// ---------- BACK SPIKES (behind or on top depending) ----------
function drawSpikes(colFn){
  const rootX = hipC[0]-20, rootY = hipC[1]-6;
  const n = 7;
  for (let i=0;i<n;i++){
    const t=i/(n-1);
    const px = rootX + t*(HDx - rootX)*0.9;
    const py = rootY + Math.sin(t*PI)*(-30) - t*30 + Math.sin(K.t*0.8 + i)*1.5;
    const hgt = (10 + spk*26)*(0.5 + Math.sin(t*PI)*0.7);
    colFn(0.7, i);
    triangle(px-8, py+6, px + spk*3, py - hgt, px+8, py+6);
  }
}

// ---------- STYLE RENDERERS ----------
if (style === 'riso') {
  // light paper ground so the ink overprint reads (bed is dark)
  noStroke(); fill((H+30)%360, 8, 95);
  push(); translate(bx-6, -86); ellipse(0, 0, 300, 300); ellipse(-90, 20, 180, 150); ellipse(90, -10, 170, 170); pop();
  // two-ink overprint with misregistration
  const passes = [[riA, -3.2, 2.4, 70], [riB, 3.0, -2.2, 70]];
  for (const [ink, ox, oy, al] of passes) {
    push(); translate(ox, oy);
    blendMode(MULTIPLY);
    noStroke(); fill(ink[0], ink[1], ink[2], al);
    drawSpikes(()=>fill(ink[0], ink[1], ink[2], al));
    for (const m of masses) geom(m);
    blendMode(BLEND);
    pop();
  }
  // halftone dots over the body
  const dn = Math.round(5 + P.density*9);
  noStroke();
  for (let iy=-dn; iy<=dn; iy++) for (let ix=-dn; ix<=dn; ix++){
    const dxx=ix/dn, dyy=iy/dn; if (dxx*dxx+dyy*dyy>1) continue;
    const px=bellyC[0]+dxx*95, py=bellyC[1]+dyy*95;
    fill(riB[0], riB[1], 30, 22);
    circle(px, py, (1 - Math.sqrt(dxx*dxx+dyy*dyy))*3.4 + fr(ix*7+iy)*1.2);
  }
} else if (style === 'fossil') {
  // bone plate + engraving hatch + stipple
  noStroke();
  for (const m of masses){ fill(boneL[0], boneL[1], boneL[2]); geom(m); }
  drawSpikes(()=>fill(boneL[0], boneL[1], boneL[2]-6));
  // contour hatch
  stroke(boneD[0], boneD[1], boneD[2], 55); strokeWeight(1); noFill();
  for (const m of masses){ if (m.k!=='ell') continue; push(); translate(m.x,m.y); rotate(m.r);
    for (let i=-2;i<=2;i++){ const yy=i*m.h*0.16; line(-m.w*0.45, yy, m.w*0.2, yy+ m.h*0.12); } pop(); }
  // stipple
  noStroke();
  const sn = Math.round(30 + P.density*50);
  for (let i=0;i<sn;i++){ fill(boneD[0], boneD[1], boneD[2], 40); const a=fr(i*3)*TAU, rr=fr(i*5); circle(bellyC[0]+Math.cos(a)*rr*80, bellyC[1]+Math.sin(a)*rr*80, 1+fr(i)*1.4); }
  stroke(boneD[0], boneD[1], boneD[2], 80); strokeWeight(1.4); noFill();
  for (const m of masses){ if (m.k==='ell'){ push(); translate(m.x,m.y); rotate(m.r); ellipse(0,0,m.w,m.h); pop(); } else geom(m); }
} else if (style === 'thermal') {
  // false-color heat: hot core -> cool rim, additive
  push(); blendMode(ADD); noStroke();
  const ramp = [[300,80,45,40],[260,85,40,45],[20,95,80,55],[45,95,95,70],[55,60,100,80]];
  for (const m of masses){
    for (let l=0;l<ramp.length;l++){
      const s=1 - l*0.17; const c=ramp[l];
      fill(c[0], c[1], c[2], c[3]*0.5);
      if (m.k==='ell'){ push(); translate(m.x,m.y); rotate(m.r); ellipse(0,0,m.w*s,m.h*s); pop(); }
      else if (l<2) geom(m);
    }
  }
  drawSpikes((d,i)=>fill(30,95,90,60));
  blendMode(BLEND); pop();
} else { // lowpoly
  drawSpikes((d,i)=>{ fill(lpBase[0], lpBase[1]*(0.8), lpBase[2]*(0.7+fr(i)*0.4)); stroke(lpBase[0],40,20,50); strokeWeight(1); });
  for (const m of masses){
    if (m.k==='ell'){
      const seg=7; push(); translate(m.x,m.y); rotate(m.r);
      for (let i=0;i<seg;i++){
        const a0=i/seg*TAU, a1=(i+1)/seg*TAU;
        const light = 0.5 + 0.5*Math.cos(a0 - 2.3); // light upper-left
        fill(lpBase[0], lpBase[1] - light*10, (lpBase[2]*(0.55 + light*0.6)) * (0.85 + fr(i+m.x)*0.2));
        stroke(lpBase[0], 45, 22, 60); strokeWeight(1);
        triangle(0,0, Math.cos(a0)*m.w*0.5, Math.sin(a0)*m.h*0.5, Math.cos(a1)*m.w*0.5, Math.sin(a1)*m.h*0.5);
      }
      pop();
    } else {
      // faceted tail: fan of triangles
      noStroke();
      for (let i=1;i<m.pts.length-1;i++){
        const light=0.5+0.4*Math.sin(i);
        fill(lpBase[0], lpBase[1]-6, lpBase[2]*(0.5+light*0.5));
        triangle(m.pts[0][0],m.pts[0][1], m.pts[i][0],m.pts[i][1], m.pts[i+1][0],m.pts[i+1][1]);
      }
      noFill(); stroke(lpBase[0],45,22,55); strokeWeight(1); geom(m);
    }
  }
}

// ---------- HEAD (all styles, drawn on top) ----------
push();
translate(HDx, HDy);
rotate(headDX*0.004 + tilt*0.5);
// head base color per style
let hf;
if (style==='riso') hf=riA;
else if (style==='fossil') hf=boneL;
else if (style==='thermal') hf=[45,90,95];
else hf=lpBase;

if (style==='thermal'){ push(); blendMode(ADD); }
// jaw (lower) opens down
noStroke();
if (style==='fossil'){ fill(boneL[0],boneL[1],boneL[2]-4); } else fill(hf[0], hf[1], hf[2]*(style==='thermal'?0.9:1), style==='thermal'?70:100);
push(); rotate(jaw*0.5);
ellipse(hr*0.55, hr*0.34, hr*1.5, hr*0.5); // lower jaw / snout bottom
// teeth
if (style!=='thermal'){ fill(0,0,98); for (let i=0;i<4;i++){ triangle(hr*0.2+i*hr*0.3, hr*0.2, hr*0.28+i*hr*0.3, hr*0.42, hr*0.36+i*hr*0.3, hr*0.2); } }
pop();
// skull + snout (upper)
if (style==='fossil'){ fill(boneL[0],boneL[1],boneL[2]); } else fill(hf[0], hf[1], hf[2], style==='thermal'?70:100);
ellipse(0, 0, hr*1.7, hr*1.5);
ellipse(hr*0.7, -hr*0.12, hr*1.5, hr*0.72); // snout
// brow ridge
fill(hf[0], Math.min(100,hf[1]+10), hf[2]*0.8, style==='thermal'?60:100);
ellipse(-hr*0.1, -hr*0.45, hr*0.9, hr*0.5);
if (style==='thermal'){ blendMode(BLEND); pop(); }
// nostril
noStroke(); fill(0,0,style==='thermal'?100:10, style==='thermal'?70:60); circle(hr*1.25, -hr*0.2, 6);
// eye
fill(0,0,100); ellipse(-hr*0.05, -hr*0.28, 18, 18);
fill(0,0,8); const look = headDX*0.02; ellipse(-hr*0.05+look, -hr*0.28, 8, 10);
fill(0,0,100,70); circle(-hr*0.05+look-2, -hr*0.28-3, 3);
// upper detail per style
if (style==='riso'){ push(); translate(-2.6,2); blendMode(MULTIPLY); noStroke(); fill(riB[0],riB[1],riB[2],55); ellipse(0,0,hr*1.7,hr*1.5); ellipse(hr*0.7,-hr*0.12,hr*1.5,hr*0.72); blendMode(BLEND); pop(); }
if (style==='fossil'){ stroke(boneD[0],boneD[1],boneD[2],80); strokeWeight(1.3); noFill(); ellipse(0,0,hr*1.7,hr*1.5); ellipse(hr*0.7,-hr*0.12,hr*1.5,hr*0.72); for(let i=-1;i<=1;i++) line(-hr*0.3, i*7, hr*1.1, i*5); }
if (style==='lowpoly'){ noFill(); stroke(lpBase[0],45,22,55); strokeWeight(1); ellipse(0,0,hr*1.7,hr*1.5); line(-hr*0.6,-hr*0.2,hr*0.9,-hr*0.1); line(-hr*0.4,hr*0.2,hr*1.2,-hr*0.1); }
pop(); // head

pop(); // world
blendMode(BLEND);
